<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{api}from'../api/admin';const rows=ref<any[]>([]),orders=ref<any[]>([]),channels=ref<any[]>([]),visible=ref(false),selected=ref<any>();const form=reactive({amount:0,reason:''});async function load(){try{[rows.value,orders.value,channels.value]=await Promise.all([api.records(),api.orders(),api.channels()])as any}catch(e:any){ElMessage.error(e.message)}}function label(list:any[],id:number,key:string){return list.find(x=>x.id===id)?.[key]||`#${id}`}function open(row:any){selected.value=row;form.amount=Number(row.adjustmentAmount||0);form.reason=row.adjustmentReason||'';visible.value=true}async function adjust(){try{await api.adjust(selected.value.id,form);ElMessage.success('金额已修正并记录日志');visible.value=false;load()}catch(e:any){ElMessage.error(e.message)}}async function confirm(row:any){try{await ElMessageBox.confirm(`确认向渠道结算 HK$${Number(row.finalAmount).toFixed(2)}？系统不会自动打款。`,'人工确认结算',{type:'warning'});await api.confirmSettlement(row.id);ElMessage.success('已确认结算');load()}catch(e:any){if(e!=='cancel'&&e!=='close'&&e?.message)ElMessage.error(e.message)}}onMounted(load);</script>
<template><div class="page"><div class="page-heading"><div><h1>结算记录</h1><p>查看公式计算结果、T+N 拆分和人工审核状态。</p></div></div><div class="table-card"><el-table :data="rows"><el-table-column label="订单" min-width="185"><template #default="s">{{label(orders,s.row.orderId,'orderNo')}}</template></el-table-column><el-table-column label="渠道" min-width="140"><template #default="s">{{label(channels,s.row.channelId,'channelName')}}</template></el-table-column><el-table-column prop="joincomTotal" label="JOINCOM总佣金" min-width="140"/><el-table-column prop="channelGross" label="渠道毛佣金" min-width="120"/><el-table-column prop="channelPayable" label="渠道应结" min-width="110"/><el-table-column prop="joincomRetained" label="JOINCOM留存" min-width="125"/><el-table-column prop="t1Amount" label="T+1" width="85"/><el-table-column prop="t3Amount" label="T+3" width="85"/><el-table-column prop="t7Amount" label="T+7" width="85"/><el-table-column prop="adjustmentAmount" label="人工调整" width="100"/><el-table-column label="最终金额" width="115"><template #default="s"><b class="money">HK${{Number(s.row.finalAmount).toFixed(2)}}</b></template></el-table-column><el-table-column label="状态" width="105"><template #default="s"><el-tag :type="s.row.status==='CONFIRMED'?'success':'warning'">{{s.row.status==='CONFIRMED'?'已确认':'待审核'}}</el-tag></template></el-table-column><el-table-column label="操作" fixed="right" width="150"><template #default="s"><el-button link :disabled="s.row.status==='CONFIRMED'" @click="open(s.row)">修正</el-button><el-button link type="primary" :disabled="s.row.status==='CONFIRMED'" @click="confirm(s.row)">确认结算</el-button></template></el-table-column></el-table></div><el-dialog v-model="visible" title="人工修正结算金额" width="520"><el-form label-position="top"><el-form-item label="调整金额（可为负数）"><el-input-number v-model="form.amount" :precision="2" style="width:100%"/></el-form-item><el-form-item label="修正原因"><el-input v-model="form.reason" type="textarea" :rows="3"/></el-form-item></el-form><template #footer><div class="dialog-footer"><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="adjust">保存修正</el-button></div></template></el-dialog></div></template>

